Execute 'FS-Filters.ipynb'. Save the results in html format in ../results. For all the runs, disable the cell execution timeout and allow errors.
Questions:
{
  "q1": "Report the best accuracy of the hybrid filter wrapper strategy.",
  "q2": "fig Report the name of the feature with the highest I-Gain."
}

arguments.command:
cd /code && python - <<'PY'
import nbformat, json
nb=nbformat.read('FS-Filters.ipynb', as_version=4)
for i,cell in enumerate(nb.cells):
    if cell.cell_type=='markdown':
        txt=cell.source.replace('\n',' ')
        if 'accuracy' in txt.lower() or 'I-Gain' in txt or 'Chi' in txt:
            print('\nCELL',i,'MD:',txt[:500])
    else:
        src=cell.source.replace('\n',' ')
        if 'accuracy' in src.lower() or 'I-Gain' in src or 'mutual' in src.lower() or 'chi' in src.lower():
            print('\nCELL',i,'CODE:',src[:500])
PY

cd /code && python - <<'PY'
import nbformat, json
nb=nbformat.read('../results/FS-Filters-executed.ipynb', as_version=4)
for i,cell in enumerate(nb.cells):
    if cell.cell_type=='code' and cell.outputs:
        print('\nCELL',i)
        for out in cell.outputs:
            if out.output_type=='execute_result':
                txt=out.get('data',{}).get('text/plain','')
                if len(txt)>500: txt=txt[:500]+'...'
                print('RESULT:',txt)
            elif out.output_type=='stream':
                print('STREAM:',out.text[:500])
            elif out.output_type=='display_data':
                txt=out.get('data',{}).get('text/plain','')
                if txt: print('DISPLAY:',txt[:500])
PY
